#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long m;
    cin >> n >> m;
    vector<vector<long long>> edges(m, vector<long long>(2));
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> edges[i][j];
        }
    }

    vector<vector<pair<int, int>>> adj(n + 1);
    for (size_t i = 0; i < edges.size(); i++) {
        adj[edges[i][0]].push_back({(int)edges[i][1], (int)i});
        adj[edges[i][1]].push_back({(int)edges[i][0], (int)i});
    }
    vector<int> tin(n + 1, 0), low(n + 1, 0), parentEdge(n + 1, -1), pos(n + 1, 0);
    int timer = 0;
    vector<pair<int, int>> bridges;
    for (int s = 1; s <= n; s++) {
        if (tin[s]) continue;
        timer++;
        tin[s] = low[s] = timer;
        vector<int> stack = {s};
        while (!stack.empty()) {
            int v = stack.back();
            if (pos[v] < (int)adj[v].size()) {
                int w = adj[v][pos[v]].first, edgeId = adj[v][pos[v]].second;
                pos[v]++;
                if (edgeId == parentEdge[v]) continue;
                if (tin[w]) {
                    low[v] = min(low[v], tin[w]);
                } else {
                    timer++;
                    tin[w] = low[w] = timer;
                    parentEdge[w] = edgeId;
                    stack.push_back(w);
                }
            } else {
                stack.pop_back();
                if (!stack.empty()) {
                    int p = stack.back();
                    low[p] = min(low[p], low[v]);
                    if (low[v] > tin[p]) bridges.push_back({min(p, v), max(p, v)});
                }
            }
        }
    }
    sort(bridges.begin(), bridges.end());
    cout << bridges.size() << "\n";
    for (const auto& b : bridges) cout << b.first << " " << b.second << "\n";

    return 0;
}

