import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long m = Long.parseLong(next());
        long[][] edges = new long[(int) m][2];
        for (int i = 0; i < edges.length; i++) {
            for (int j = 0; j < edges[i].length; j++) {
                edges[i][j] = Long.parseLong(next());
            }
        }

        int nodes = (int) n;
        int[] head = new int[nodes + 2];
        for (int i = 0; i < edges.length; i++) {
            head[(int) edges[i][0] + 1]++;
            head[(int) edges[i][1] + 1]++;
        }
        for (int v = 1; v <= nodes; v++) head[v + 1] += head[v];
        int[] to = new int[2 * edges.length];
        int[] eid = new int[2 * edges.length];
        int[] fill = new int[nodes + 2];
        for (int i = 0; i < edges.length; i++) {
            int a = (int) edges[i][0], b = (int) edges[i][1];
            to[head[a] + fill[a]] = b;
            eid[head[a] + fill[a]] = i;
            fill[a]++;
            to[head[b] + fill[b]] = a;
            eid[head[b] + fill[b]] = i;
            fill[b]++;
        }
        int[] tin = new int[nodes + 1], low = new int[nodes + 1], parentEdge = new int[nodes + 1], pos = new int[nodes + 1];
        Arrays.fill(parentEdge, -1);
        int timer = 0;
        long[] bridges = new long[nodes + 1];
        int bridgeCount = 0;
        int[] stack = new int[nodes + 1];
        for (int s = 1; s <= nodes; s++) {
            if (tin[s] != 0) continue;
            timer++;
            tin[s] = low[s] = timer;
            int top = 0;
            stack[top++] = s;
            while (top > 0) {
                int v = stack[top - 1];
                if (head[v] + pos[v] < head[v + 1]) {
                    int k = head[v] + pos[v];
                    pos[v]++;
                    int w = to[k], edgeId = eid[k];
                    if (edgeId == parentEdge[v]) continue;
                    if (tin[w] != 0) {
                        low[v] = Math.min(low[v], tin[w]);
                    } else {
                        timer++;
                        tin[w] = low[w] = timer;
                        parentEdge[w] = edgeId;
                        stack[top++] = w;
                    }
                } else {
                    top--;
                    if (top > 0) {
                        int p = stack[top - 1];
                        low[p] = Math.min(low[p], low[v]);
                        if (low[v] > tin[p]) bridges[bridgeCount++] = (long) Math.min(p, v) * (nodes + 1) + Math.max(p, v);
                    }
                }
            }
        }
        Arrays.sort(bridges, 0, bridgeCount);
        StringBuilder out = new StringBuilder();
        out.append(bridgeCount).append("\n");
        for (int i = 0; i < bridgeCount; i++) out.append(bridges[i] / (nodes + 1)).append(" ").append(bridges[i] % (nodes + 1)).append("\n");
        System.out.print(out);
    }
}
